'use strict';
let fundingAward=null,fundingId=null,fundingSequence=0,fundingPage=1;
const fundingMoney=n=>typeof n!=='number'||!Number.isFinite(n)?'Unavailable':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
async function loadSavedFunding(){try{const r=await fetch('/api/funding');if(!r.ok)throw new Error();const data=await r.json();$('savedFunding').innerHTML='<option value="">Select a saved contract</option>'+data.awards.map(a=>`<option value="${esc(a.awardId)}">${esc(a.awardId)} / ${a.rows} transactions</option>`).join('');if(fundingId)$('savedFunding').value=fundingId;}catch{}}
function renderFunding(){const a=fundingAward,s=a.summary;
 $('fundingSummary').innerHTML=`<section class="panel"><h3>${esc(a.awardId)}</h3><p>${a.complete?'All pages returned by source collected':'PARTIAL HISTORY / COLLECTION CAP REACHED'} · ${a.transactions.length} transactions · Retrieved ${esc(new Date(a.fetchedAt).toLocaleString())}</p><p>Comparison through ${esc(s.asOf)} (New York calendar date). ${s.futureRows} future-dated records excluded.</p><div class="metrics"><article><span>NET OBLIGATIONS THROUGH DATE</span><strong>${esc(fundingMoney(s.total.net))}</strong></article><article><span>POSITIVE FUNDING</span><strong>${esc(fundingMoney(s.total.positive))}</strong></article><article><span>DEOBLIGATIONS</span><strong>${esc(fundingMoney(s.total.deobligations))}</strong></article></div><p class="muted">Missing amounts: ${s.total.missing}. Invalid dates: ${s.total.invalidDates}. Unavailable means incomplete collection or missing/invalid source data.</p><div class="table-wrap"><table><thead><tr><th>WINDOW</th><th>CURRENT NET</th><th>PREVIOUS NET</th><th>CHANGE</th><th>PERCENT CHANGE</th></tr></thead><tbody>${s.windows.map(w=>`<tr><td><b>${w.days} DAYS</b><small>${esc(w.currentStart)} → ${esc(w.currentEnd)}<br>Previous: ${esc(w.previousStart)} → ${esc(w.previousEnd)}</small></td><td>${esc(fundingMoney(w.current.net))}</td><td>${esc(fundingMoney(w.previous.net))}</td><td>${esc(fundingMoney(w.change))}</td><td>${w.percentChange===null?'Unavailable':esc(w.percentChange.toFixed(1)+'%')}</td></tr>`).join('')}</tbody></table></div><p class="muted">Percentage change requires a positive previous-period net. A zero or negative baseline is shown without a percentage.</p><a href="${esc(a.sourceUrl)}" target="_blank" rel="noopener">OPEN PRIME AWARD SOURCE</a></section>`;
 renderFundingTransactions();
}
function renderFundingTransactions(){const rows=fundingAward.transactions,start=(fundingPage-1)*25;$('fundingPage').textContent=`PAGE ${fundingPage} / ${Math.max(1,Math.ceil(rows.length/25))}`;$('fundingRows').innerHTML=rows.slice(start,start+25).map(r=>`<tr><td>${esc(r.action_date)}</td><td>${esc(fundingMoney(r.federal_action_obligation))}</td><td>${esc(r.action_type_description||'Not reported')}<small>Modification: ${esc(r.modification_number)}<br>${esc(r.id)}</small></td><td>${esc(r.description)}</td></tr>`).join('')||'<tr><td colspan="4">The source returned no transactions for this award.</td></tr>';$('fundingPrevious').disabled=fundingPage<=1;$('fundingNext').disabled=start+25>=rows.length;}
async function openFunding(id,refresh=false){const sequence=++fundingSequence;fundingId=id;fundingAward=null;fundingPage=1;showView('funding');$('refreshFunding').disabled=true;$('fundingSummary').innerHTML='';$('fundingRows').innerHTML='<tr><td colspan="4">Retrieving transaction history…</td></tr>';$('fundingPrevious').disabled=true;$('fundingNext').disabled=true;$('fundingPage').textContent='';$('fundingStatus').textContent=refresh?'Collecting USAspending transactions; this can take up to a minute…':'Loading the saved funding snapshot…';
 try{const response=await fetch('/api/funding/history'+(refresh?'':'?awardId='+encodeURIComponent(id)),refresh?{method:'POST',headers:{'Content-Type':'application/json','X-Sentinel-Action':'scan'},body:JSON.stringify({awardId:id})}:{});const data=await response.json();if(sequence!==fundingSequence)return;if(!response.ok){if(data.cached){fundingAward=data.cached;renderFunding();$('fundingStatus').textContent=`Refresh failed: ${data.error}. Showing the previously saved snapshot; it has not been refreshed.`;}else throw new Error(data.error||'Funding history unavailable');}else{fundingAward=data;renderFunding();$('fundingStatus').textContent=refresh?'Transaction history retrieved and saved locally.':'Saved snapshot loaded. Use Refresh to check the source for updates.';}await loadSavedFunding();}catch(e){if(sequence===fundingSequence){$('fundingRows').innerHTML='<tr><td colspan="4">No transaction history loaded. Retry the collection.</td></tr>';$('fundingStatus').textContent=`Funding history failed: ${e.message}. No estimated transactions substituted.`;}}finally{if(sequence===fundingSequence)$('refreshFunding').disabled=false;}
}
$('savedFunding').onchange=()=>{if($('savedFunding').value)openFunding($('savedFunding').value,false)};
$('refreshFunding').onclick=()=>{if(fundingId)openFunding(fundingId,true)};
$('fundingPrevious').onclick=()=>{fundingPage--;renderFundingTransactions()};$('fundingNext').onclick=()=>{fundingPage++;renderFundingTransactions()};
document.querySelector('[data-view="funding"]').addEventListener('click',loadSavedFunding);loadSavedFunding();

